import{H as e,V as t,et as n,j as r}from"./chunks/framework.DKIRGhFK.js";import{_p as i}from"./chunks/assets.CUKu7Ix7.js";var a=JSON.parse(`{"title":"思路","description":"","frontmatter":{},"headers":[],"relativePath":"java/login-validation/approach.md","filePath":"java/login-validation/approach.md"}`),o={name:`java/login-validation/approach.md`};function s(r,a,o,s,c,l){return n(),t(`div`,null,[...a[0]||=[e(`<h1 id="思路" tabindex="-1">思路 <a class="header-anchor" href="#思路" aria-label="Permalink to “思路”">​</a></h1><p>什么是登录校验？</p><p>所谓登录校验，指的是我们在服务器端接收到浏览器发送过来的请求之后，首先我们要对请求进行校验。先要校验一下用户登录了没有，如果用户已经登录了，就直接执行对应的业务操作就可以了；如果用户没有登录，此时就不允许他执行相关的业务操作，直接给前端响应一个错误的结果，最终跳转到登录页面，要求他登录成功之后，再来访问对应的数据。</p><p>了解完什么是登录校验之后，接下来我们分析一下登录校验大概的实现思路。</p><p>首先我们在宏观上先有一个认知：</p><p>前面在讲解HTTP协议的时候，我们提到HTTP协议是无状态协议。什么又是无状态的协议？</p><p>所谓无状态，指的是每一次请求都是独立的，下一次请求并不会携带上一次请求的数据。而浏览器与服务器之间进行交互，基于HTTP协议也就意味着现在我们通过浏览器来访问了登陆这个接口，实现了登陆的操作，接下来我们在执行其他业务操作时，服务器也并不知道这个员工到底登陆了没有。因为HTTP协议是无状态的，两次请求之间是独立的，所以是无法判断这个员工到底登陆了没有。</p><p><img src="`+i+`" alt="imagepng" width="1414" height="449"></p><p>那应该怎么来实现登录校验的操作呢？具体的实现思路可以分为两部分：</p><ol><li><p>在员工登录成功后，需要将用户登录成功的信息存起来，记录用户已经登录成功的标记。</p></li><li><p>在浏览器发起请求时，需要在服务端进行统一拦截，拦截后进行登录校验。</p></li></ol><p>想要判断员工是否已经登录，我们需要在员工登录成功之后，存储一个登录成功的标记，接下来在每一个接口方法执行之前，先做一个条件判断，判断一下这个员工到底登录了没有。如果是登录了，就可以执行正常的业务操作，如果没有登录，会直接给前端返回一个错误的信息，前端拿到这个错误信息之后会自动的跳转到登录页面。</p><p>我们程序中所开发的查询功能、删除功能、添加功能、修改功能，都需要使用以上套路进行登录校验。此时就会出现：相同代码逻辑，每个功能都需要编写，就会造成代码非常繁琐。</p><p>为了简化这块操作，我们可以使用一种技术：统一拦截技术。</p><p>通过统一拦截的技术，我们可以来拦截浏览器发送过来的所有的请求，拦截到这个请求之后，就可以通过请求来获取之前所存入的登录标记，在获取到登录标记且标记为登录成功，就说明员工已经登录了。如果已经登录，我们就直接放行(意思就是可以访问正常的业务接口了)。</p><p>我们要完成以上操作，会涉及到web开发中的两个技术：</p><ol><li><p>会话技术：用户登录成功之后，在后续的每一次请求中，都可以获取到该标记。</p></li><li><p>统一拦截技术：过滤器Filter、拦截器Interceptor</p></li></ol><p>下面我们先学习会话技术，然后再学习统一拦截技术。</p>`,17)]])}var c=r(o,[[`render`,s]]);export{a as __pageData,c as default};